const express = require('express');
const Joi = require('joi');
const { SmartGridManager, PropertyUtilityAccount } = require('../services/grid');

const app = express();
app.use(express.json());

const shutoffSchema = Joi.object({
  meterSerialNumber: Joi.string().hex().length(16).required(),
  reasonCode: Joi.string().valid('TENANT_MOVE_OUT', 'MAINTENANCE', 'BILLING_HOLD').required()
});

const validateShutoff = (req, res, next) => {
  const { error, value } = shutoffSchema.validate(req.body);
  if (error) {
    return res.status(400).json({ error: error.details[0].message });
  }
  req.shutoffPayload = value;
  next();
};

app.post('/api/utilities/smart-meter/disconnect', validateShutoff, async (req, res) => {
  if (!req.user || !req.user.id) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const { meterSerialNumber, reasonCode } = req.shutoffPayload;

  // Confirm that the meter belongs to a property account owned by the caller or caller has operator role
  const isAuthorized = await PropertyUtilityAccount.isOwnerOrOperator(
    req.user.id,
    meterSerialNumber
  );

  if (!isAuthorized) {
    return res.status(403).json({ error: 'Access denied: not authorized to manage this smart meter' });
  }

  await SmartGridManager.issueRemoteDisconnectCommand(meterSerialNumber, reasonCode);
  res.json({ status: 'DISCONNECTED', meterSerialNumber });
});

app.listen(7008);
